action.command:
cat > /tmp/verify/komono.js <<'EOF'
const { chromium } = require('playwright');
(async () => {
    const browser = await chromium.launch();
    const page = await browser.newPage();
    const errs = [], reqf = [];
    page.on('pageerror', e => errs.push(e.message));
    page.on('console', m => { if (m.type()==='error') errs.push('console: '+m.text()); });
    page.on('requestfailed', r => reqf.push(r.url()));
    await page.goto('http://localhost/examples/komono/index.html', { waitUntil: 'networkidle' });
    await page.waitForTimeout(6000);
    const bodyText = (await page.$eval('body', el => el.innerText).catch(()=>'')).slice(0, 300);
    console.log('KOMONO title: ' + await page.title());
    console.log('KOMONO body snippet: ' + JSON.stringify(bodyText));
    console.log('KOMONO errors: ' + JSON.stringify(errs));
    console.log('KOMONO failedReqs: ' + JSON.stringify(reqf));
    await browser.close();
})().catch(e => { console.error('K_FAILED', e); process.exit(1); });
EOF
cd /tmp/verify && node komono.js 2>&1 | tail -10

